public enum DailyQuotesCatalog {
    public static let verses: [OfflineDailyVerse] = [
        OfflineDailyVerse(surahNumber: 1, ayahNumber: 2, textAr: "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", meaningEn: "All praise is due to Allah, Lord of the worlds.", meaningTr: "Hamd, âlemlerin Rabbi Allah'a mahsustur.", meaningUr: "سب تعریفیں اللہ کے لیے ہیں جو تمام جہانوں کا رب ہے۔", surahNameAr: "الفاتحة", surahNameEn: "Al-Fatihah"),
        OfflineDailyVerse(surahNumber: 2, ayahNumber: 152, textAr: "فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ", meaningEn: "So remember Me; I will remember you. And be grateful to Me and do not deny Me.", meaningTr: "Öyleyse beni anın ki ben de sizi anayım. Bana şükredin, sakın nankörlük etmeyin.", meaningUr: "پس تم مجھے یاد رکھو میں تمہیں یاد رکھوں گا، اور میرا شکر ادا کرو اور ناشکری نہ کرو۔", surahNameAr: "البقرة", surahNameEn: "Al-Baqarah"),
        OfflineDailyVerse(surahNumber: 2, ayahNumber: 186, textAr: "وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ", meaningEn: "And when My servants ask you concerning Me, indeed I am near. I respond to the invocation of the supplicant when he calls upon Me.", meaningTr: "Kullarım sana beni sorduğunda bilsinler ki ben şüphesiz onlara yakınım. Bana dua ettiğinde dua edenin dileğine karşılık veririm.", meaningUr: "اور جب میرے بندے آپ سے میرے متعلق پوچھیں تو بیشک میں قریب ہوں، دعا کرنے والے کی دعا قبول کرتا ہوں جب وہ مجھے پکارتا ہے۔", surahNameAr: "البقرة", surahNameEn: "Al-Baqarah"),
        OfflineDailyVerse(surahNumber: 2, ayahNumber: 286, textAr: "لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا", meaningEn: "Allah does not charge a soul except with that within its capacity.", meaningTr: "Allah hiçbir kimseye gücünün yeteceğinden fazlasını yüklemez.", meaningUr: "اللہ کسی جان پر اس کی طاقت سے بڑھ کر بوجھ نہیں ڈالتا۔", surahNameAr: "البقرة", surahNameEn: "Al-Baqarah"),
        OfflineDailyVerse(surahNumber: 3, ayahNumber: 139, textAr: "وَلَا تَهِنُوا وَلَا تَحْزَنُوا وَأَنتُمُ الْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ", meaningEn: "So do not weaken and do not grieve, and you will be superior if you are believers.", meaningTr: "Gevşeklik göstermeyin, üzülmeyin; eğer inanmışsanız şüphesiz en üstün olan sizsiniz.", meaningUr: "اور کمزور نہ پڑو اور غم نہ کرو، اور تم ہی غالب رہو گے اگر تم مومن ہو۔", surahNameAr: "آل عمران", surahNameEn: "Ali 'Imran"),
        OfflineDailyVerse(surahNumber: 13, ayahNumber: 28, textAr: "أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ", meaningEn: "Unquestionably, by the remembrance of Allah hearts are assured.", meaningTr: "Bilesiniz ki kalpler ancak Allah'ı anmakla huzur bulur.", meaningUr: "خبردار! اللہ کے ذکر ہی سے دلوں کو اطمینان نصیب ہوتا ہے۔", surahNameAr: "الرعد", surahNameEn: "Ar-Ra'd"),
        OfflineDailyVerse(surahNumber: 14, ayahNumber: 7, textAr: "لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ", meaningEn: "If you are grateful, I will surely increase you in favor.", meaningTr: "Eğer şükrederseniz elbette size nimetimi artırırım.", meaningUr: "اگر تم شکر کرو گے تو میں تمہیں ضرور زیادہ دوں گا۔", surahNameAr: "إبراهيم", surahNameEn: "Ibrahim"),
        OfflineDailyVerse(surahNumber: 29, ayahNumber: 69, textAr: "وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا ۚ وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ", meaningEn: "And those who strive for Us — We will surely guide them to Our ways. And indeed, Allah is with the doers of good.", meaningTr: "Bizim uğrumuzda cihad edenlere gelince, elbette onları bize ulaşan yollara iletiriz. Şüphesiz Allah iyilik edenlerle beraberdir.", meaningUr: "اور جن لوگوں نے ہماری راہ میں کوشش کی، ہم انہیں ضرور اپنے راستے دکھا دیں گے، اور بیشک اللہ نیکی کرنے والوں کے ساتھ ہے۔", surahNameAr: "العنكبوت", surahNameEn: "Al-'Ankabut"),
        OfflineDailyVerse(surahNumber: 39, ayahNumber: 53, textAr: "لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ ۚ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا", meaningEn: "Do not despair of the mercy of Allah. Indeed, Allah forgives all sins.", meaningTr: "Allah'ın rahmetinden ümit kesmeyin. Şüphesiz Allah bütün günahları bağışlar.", meaningUr: "اللہ کی رحمت سے ناامید نہ ہو، بیشک اللہ تمام گناہ بخش دیتا ہے۔", surahNameAr: "الزمر", surahNameEn: "Az-Zumar"),
        OfflineDailyVerse(surahNumber: 65, ayahNumber: 3, textAr: "وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ", meaningEn: "And whoever relies upon Allah — then He is sufficient for him.", meaningTr: "Kim Allah'a tevekkül ederse O, ona yeter.", meaningUr: "اور جو اللہ پر بھروسہ کرے تو وہ اس کے لیے کافی ہے۔", surahNameAr: "الطلاق", surahNameEn: "At-Talaq"),
        OfflineDailyVerse(surahNumber: 94, ayahNumber: 5, textAr: "فَإِنَّ مَعَ الْعُسْرِ يُسْرًا", meaningEn: "For indeed, with hardship comes ease.", meaningTr: "Şüphesiz güçlükle beraber bir kolaylık vardır.", meaningUr: "پس بیشک مشکل کے ساتھ آسانی ہے۔", surahNameAr: "الشرح", surahNameEn: "Ash-Sharh"),
        OfflineDailyVerse(surahNumber: 94, ayahNumber: 6, textAr: "إِنَّ مَعَ الْعُسْرِ يُسْرًا", meaningEn: "Indeed, with hardship comes ease.", meaningTr: "Gerçekten güçlükle beraber bir kolaylık vardır.", meaningUr: "بیشک مشکل کے ساتھ آسانی ہے۔", surahNameAr: "الشرح", surahNameEn: "Ash-Sharh"),
    ]

    public static let hadiths: [OfflineDailyHadith] = [
        OfflineDailyHadith(id: "1", textAr: "إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ.", translationEn: "Actions are according to intentions, and everyone will get what was intended. Whoever migrated for Allah and His Messenger, his migration is for Allah and His Messenger; and whoever migrated for worldly gain or to marry a woman, his migration is for that.", translationTr: "", translationUr: "", narratorAr: "عن أمير المؤمنين عمر بن الخطاب رضي الله عنه", narratorEn: "Narrated by Umar ibn al-Khattab (RA)", referenceAr: "صحيح البخاري وصحيح مسلم - الحديث الأول من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 1 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "هذا الحديث أصل عظيم من أصول الدين وقاعدة تدور عليها جميع الأعمال، فالنية الصادقة شرط لقبول كل عبادة وقربة.", explanationEn: "A foundational principle of Islam: all deeds are evaluated by sincerity and the underlying intention."),
        OfflineDailyHadith(id: "2", textAr: "الإِسْلاَمُ أَنْ تَشْهَدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَتُقِيمَ الصَّلاَةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلاً. الإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ، وَمَلاَئِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ. الإِحْسَانُ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ.", translationEn: "Islam is to testify that there is no god but Allah and Muhammad is His messenger, establish prayer, give zakah, fast Ramadan, and perform pilgrimage if able. Iman is to believe in Allah, His angels, His books, His messengers, the Last Day, and destiny its good and evil. Ihsan is to worship Allah as though you see Him, for if you see Him not, He sees you.", translationTr: "", translationUr: "", narratorAr: "عن عمر بن الخطاب رضي الله عنه", narratorEn: "Narrated by Umar ibn al-Khattab (RA)", referenceAr: "صحيح مسلم - الحديث الثاني من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 2 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "يُعرف هذا الحديث بأم السنة لاشتماله على جميع مراتب الدين الثلاث: ظاهر الإسلام، وباطن الإيمان، وغاية المراقبة في الإحسان.", explanationEn: "Encompasses the three levels of Islam: outward acts of devotion, inner faith, and the height of God-consciousness."),
        OfflineDailyHadith(id: "3", textAr: "بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ.", translationEn: "Islam is built upon five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah, establishing the prayer, paying the zakah, performing Hajj to the House, and fasting Ramadan.", translationTr: "", translationUr: "", narratorAr: "عن عبد الله بن عمر رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Umar (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث الثالث من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 3 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "شبه النبي صلى الله عليه وسلم الإسلام بالبنيان المحكم، وأركانه الخمسة هي الأعمدة التي يقوم عليها.", explanationEn: "Metaphor of a sturdy building supported by its five structural pillars."),
        OfflineDailyHadith(id: "4", textAr: "مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ.", translationEn: "Whoever innovates something in this matter of ours (religion) that is not part of it, will have it rejected.", translationTr: "", translationUr: "", narratorAr: "عن أم المؤمنين عائشة رضي الله عنها", narratorEn: "Narrated by Aisha (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث الخامس من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 5 of An-Nawawi", categoryAr: "اتباع السنة", categoryEn: "Following the Sunnah", explanationAr: "ميزان الأعمال الظاهرة، فكما أن حديث النيات ميزان الباطن، فهذا الحديث ميزان مطابقة العمل لشرع الله وسنة نبيه.", explanationEn: "The benchmark for external actions: any deed not adhering to the Quran and authentic Sunnah is rejected."),
        OfflineDailyHadith(id: "5", textAr: "إِنَّ الْحَلاَلَ بَيِّنٌ وَإِنَّ الْحَرَامَ بَيِّنٌ وَبَيْنَهُمَا مُشْتَبِهَاتٌ لاَ يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ، أَلاَ وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلاَ وَإِنَّ حِمَى اللَّهِ مَحَارِمُهُ، أَلاَ وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ أَلاَ وَهِيَ الْقَلْبُ.", translationEn: "That which is lawful is clear and that which is unlawful is clear, and between the two of them are doubtful matters about which many people do not know. Thus he who avoids doubtful matters clears himself in regard to his religion and his honor, but he who falls into doubtful matters falls into that which is unlawful, like the shepherd who pastures around a sanctuary, all but grazing therein. Truly every king has a sanctuary, and truly Allah's sanctuary is His prohibitions. Truly, in the body there is a morsel of flesh which, if it be whole, all the body is whole and which, if it be diseased, all of it is diseased. Truly, it is the heart.", translationTr: "", translationUr: "", narratorAr: "عن النعمان بن بشير رضي الله عنه", narratorEn: "Narrated by An-Nu'man ibn Bashir (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث السادس من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 6 of An-Nawawi", categoryAr: "اتباع السنة", categoryEn: "Following the Sunnah", explanationAr: "قاعدة الورع وصلاح القلوب، فالابتعاد عن الشبهات صيانة لدين المسلم وسلامة لقلبه.", explanationEn: "The golden rule of pious precaution and heart purification: steering clear of ambiguity preserves faith and integrity."),
        OfflineDailyHadith(id: "6", textAr: "الدِّينُ النَّصِيحَةُ. قُلْنَا: لِمَنْ؟ قَالَ: لِلَّهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلأَئِمَّةِ الْمُسْلِمِينَ، وَعَامَّتِهِمْ.", translationEn: "The religion is sincerity. We said: To whom? He said: To Allah, His Book, His Messenger, and to the leaders of the Muslims and their common folk.", translationTr: "", translationUr: "", narratorAr: "عن تميم الداري رضي الله عنه", narratorEn: "Narrated by Tamim ad-Dari (RA)", referenceAr: "صحيح مسلم - الحديث السابع من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 7 of An-Nawawi", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "النصيحة كلمة جامعة تعني إرادة الخير للمنصوح له والقيام بحقوقه بإخلاص وأمانة.", explanationEn: "Defines sincere goodwill and fulfilling duties toward Allah, His revelation, leaders, and fellow humanity."),
        OfflineDailyHadith(id: "7", textAr: "مِنْ حُسْنِ إِسْلاَمِ الْمَرْءِ تَرْكُهُ مَا لاَ يَعْنِيهِ.", translationEn: "Part of the perfection of one's Islam is his leaving that which does not concern him.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "سنن الترمذي وابن ماجه (حسن) - الحديث الثاني عشر من الأربعين النووية", referenceEn: "Sunan at-Tirmidhi & Sunan Ibn Majah (Hasan) - Hadith 12 of An-Nawawi", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "حفظ الوقت واللسان والجوارح عما لا فائدة فيه في دين أو دنيا، وهو عنوان سلامة الصدر ورجاحة العقل.", explanationEn: "Advises investing time and energy into beneficial pursuits while abandoning meddling in trivia."),
        OfflineDailyHadith(id: "8", textAr: "لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ.", translationEn: "None of you truly believes until he loves for his brother what he loves for himself.", translationTr: "", translationUr: "", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث الثالث عشر من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 13 of An-Nawawi", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "كمال الإيمان يقتضي سلامة القلب من الغل والحسد، وتمني الخير والنفع لكل مسلم كما يتمناه لنفسه.", explanationEn: "True faith demands eradicating malice and genuinely wishing goodness, guidance, and prosperity for others."),
        OfflineDailyHadith(id: "9", textAr: "كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: دَمُهُ، وَمَالُهُ، وَعِرْضُهُ.", translationEn: "All of a Muslim is sacred to another Muslim: his blood, his wealth, and his honor.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح مسلم - الحديث الخامس والثلاثون من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 35 of An-Nawawi", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "حرمة المسلم أعظم عند الله من حرمة الكعبة، والاعتداء عليه بالقول أو الفعل من كبائر الذنوب.", explanationEn: "Proclaims the absolute sanctity of human life, dignity, property, and personal honor in Islamic ethics."),
        OfflineDailyHadith(id: "10", textAr: "أَنَّ رَجُلاً قَالَ لِلنَّبِيِّ صلى الله عليه وسلم: أَوْصِنِي. قَالَ: «لاَ تَغْضَبْ». فَرَدَّدَ مِرَارًا، قَالَ: «لاَ تَغْضَبْ».", translationEn: "A man said to the Prophet (PBUH): Advise me. He said: Do not become angry. The man repeated his request several times, and he said: Do not become angry.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح البخاري - الحديث السادس عشر من الأربعين النووية", referenceEn: "Sahih al-Bukhari - Hadith 16 of An-Nawawi", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "الغضب جماع الشر، واجتنابه ومجاهدة النفس عند ثورانه مفتاح كل خير وبر وسلامة.", explanationEn: "Self-restraint in moments of fury prevents destruction and opens the doors of wisdom and mercy."),
        OfflineDailyHadith(id: "11", textAr: "إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، وَلْيُرِحْ ذَبِيحَتَهُ.", translationEn: "Verily Allah has prescribed proficiency and kindness in all things. So if you kill, kill well; and if you slaughter, slaughter well. Let each one of you sharpen his blade and let him spare pain to the animal he slaughters.", translationTr: "", translationUr: "", narratorAr: "عن شداد بن أوس رضي الله عنه", narratorEn: "Narrated by Shaddad ibn Aws (RA)", referenceAr: "صحيح مسلم - الحديث السابع عشر من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 17 of An-Nawawi", categoryAr: "الرحمة والرفق", categoryEn: "Mercy & Gentleness", explanationAr: "الإسلام دين الرحمة الشاملة والإتقان في كل عمل حتى في موضع الذبح وإراحة الحيوان.", explanationEn: "Manifests Islamic mercy and professional excellence across every single domain of life."),
        OfflineDailyHadith(id: "12", textAr: "يَا غُلاَمُ إِنِّي أُعَلِّمُكَ كَلِمَاتٍ: احْفَظِ اللَّهَ يَحْفَظْكَ، احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ، وَاعْلَمْ أَنَّ الأُمَّةَ لَوِ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ لَمْ يَنْفَعُوكَ إِلاَّ بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَكَ، وَلَوِ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ لَمْ يَضُرُّوكَ إِلاَّ بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ عَلَيْكَ، رُفِعَتِ الأَقْلاَمُ وَجَفَّتِ الصُّحُفُ.", translationEn: "Young man, I shall teach you some words: Be mindful of Allah and He will protect you. Be mindful of Allah and you will find Him before you. If you ask, ask of Allah; if you seek help, seek help of Allah. Know that if the nation gathered to benefit you, they would not benefit you except with what Allah has decreed for you; and if they gathered to harm you, they would not harm you except with what Allah has decreed against you. The pens have been lifted and the pages have dried.", translationTr: "", translationUr: "", narratorAr: "عن عبد الله بن عباس رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Abbas (RA)", referenceAr: "سنن الترمذي - الحديث التاسع عشر من الأربعين النووية (صحيح)", referenceEn: "Sunan at-Tirmidhi - Hadith 19 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "وصية نبوية جامعة ترسى في القلب التوحيد الخالص، واليقين بالقضاء والقدر، والتوكل على الله وحده.", explanationEn: "Masterful instruction cultivating sincere reliance upon Allah and certainty in divine decree."),
        OfflineDailyHadith(id: "13", textAr: "قُلْتُ: يَا رَسُولَ اللَّهِ قُلْ لِي فِي الإِسْلاَمِ قَوْلاً لاَ أَسْأَلُ عَنْهُ أَحَدًا غَيْرَكَ. قَالَ: «قُلْ آمَنْتُ بِاللَّهِ ثُمَّ اسْتَقِمْ».", translationEn: "I said: O Messenger of Allah, tell me something about Islam which I can ask of no one but you. He said: Say: I believe in Allah, and then be steadfast.", translationTr: "", translationUr: "", narratorAr: "عن سفيان بن عبد الله الثقفي رضي الله عنه", narratorEn: "Narrated by Sufyan ibn Abdullah (RA)", referenceAr: "صحيح مسلم - الحديث الحادي والعشرون من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 21 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "جمع النبي صلى الله عليه وسلم في كلمتين أصول الإيمان الظاهر والباطن، والثبات على طاعة الله حتى الممات.", explanationEn: "Concise wisdom condensing faith into sincere belief followed by lifelong perseverance."),
        OfflineDailyHadith(id: "14", textAr: "مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالآخِرَةِ، وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ، وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ يَتْلُونَ كِتَابَ اللَّهِ وَيَتَدَارَسُونَهُ بَيْنَهُمْ إِلاَّ نَزَلَتْ عَلَيْهِمُ السَّكِينَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَحَفَّتْهُمُ الْمَلاَئِكَةُ، وَذَكَرَهُمُ اللَّهُ فِيمَنْ عِنْدَهُ، وَمَنْ بَطَّأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ.", translationEn: "Whoever relieves a believer's distress in this world, Allah will relieve his distress on the Day of Resurrection. Whoever eases the hardship of an insolvent debtor, Allah will ease his hardship in this world and the Hereafter. Whoever conceals the faults of a Muslim, Allah will conceal his faults in this world and the Hereafter. Allah helps His servant as long as the servant helps his brother. Whoever travels a path seeking knowledge, Allah makes easy for him a path to Paradise. No people gather in one of the houses of Allah, reciting the Book of Allah and studying it among themselves, but tranquility descends upon them, mercy covers them, the angels surround them, and Allah mentions them among those who are with Him. And whoever is held back by his deeds will not be hastened forward by his lineage.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح مسلم - الحديث السادس والثلاثون من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 36 of An-Nawawi", categoryAr: "العلم", categoryEn: "Knowledge", explanationAr: "حديث عظيم في فضل قضاء حوائج الناس، والتفريج عن المكروبين، وطلب العلم الشرعي، ومجالس الذكر.", explanationEn: "Glorious incentive for helping neighbors, easing distress, seeking knowledge, and gathering in remembrance of Allah."),
        OfflineDailyHadith(id: "15", textAr: "إِنَّ اللَّهَ قَالَ: مَنْ عَادَى لِي وَلِيًّا فَقَدْ آذَنْتُهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إِلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إِلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَإِنْ سَأَلَنِي لأُعْطِيَنَّهُ، وَلَئِنِ اسْتَعَاذَنِي لأُعِيذَنَّهُ.", translationEn: "Allah said: Whoever shows enmity to a pious worshipper of Mine, I declare war on him. My servant draws not near to Me with anything more loved by Me than what I have enjoined upon him, and My servant continues to draw near to Me with voluntary works so that I shall love him. When I love him, I become his hearing with which he hears, his seeing with which he sees, his hand with which he strikes, and his foot with which he walks. Were he to ask of Me, I would surely give it to him; and were he to ask Me for refuge, I would surely grant it.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه (حديث قدسي)", narratorEn: "Narrated by Abu Hurairah (RA) - Hadith Qudsi", referenceAr: "صحيح البخاري - الحديث الثامن والثلاثون من الأربعين النووية", referenceEn: "Sahih al-Bukhari - Hadith 38 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "أشرف حديث في بيان منزلة أولياء الله الصالحين، وفضل المحافظة على الفرائض والإكثار من النوافل.", explanationEn: "Delineates how performing obligatory deeds followed by voluntary acts earns Allah's direct divine love and protection."),
        OfflineDailyHadith(id: "16", textAr: "مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لاَ يَذْكُرُ رَبَّهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ.", translationEn: "The example of the one who remembers his Lord in comparison to the one who does not remember his Lord is that of the living and the dead.", translationTr: "", translationUr: "", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa Al-Ash'ari (RA)", referenceAr: "صحيح البخاري ومسلم - باب فضل الذكر", referenceEn: "Sahih al-Bukhari & Sahih Muslim", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "الذكر حياة القلوب والأرواح، فالغافل عن ذكر الله ميت وإن كان يمشي بين الأحياء، والذاكر حي القلب بنور ربه.", explanationEn: "Remembering Allah infuses true life into hearts; abandoning remembrance results in spiritual death despite physical vitality."),
        OfflineDailyHadith(id: "17", textAr: "أَفْضَلُ الذِّكْرِ: لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَفْضَلُ الدُّعَاءِ: الْحَمْدُ لِلَّهِ.", translationEn: "The best dhikr is 'La ilaha illa Allah' (There is no god but Allah), and the best supplication is 'Alhamdulillah' (Praise be to Allah).", translationTr: "", translationUr: "", narratorAr: "عن جابر بن عبد الله رضي الله عنهما", narratorEn: "Narrated by Jabir ibn Abdullah (RA)", referenceAr: "جامع الترمذي وسنن ابن ماجه (حسن)", referenceEn: "Jami at-Tirmidhi & Sunan Ibn Majah (Hasan)", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "كلمة التوحيد أعظم كلمة قالها النبيون، والحمد اعتراف بالنعمة وثناء على المنعم سبحانه.", explanationEn: "The proclamation of Tawhid is the greatest statement uttered, while praising Allah is the pinnacle of gratitude and prayer."),
        OfflineDailyHadith(id: "18", textAr: "كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ.", translationEn: "Two words are light on the tongue, heavy on the Scale, and beloved to the Most Merciful: 'Subhan Allahi wa bihamdihi, Subhan Allahil-'Azeem' (Glory be to Allah and His praise, Glory be to Allah the Magnificent).", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح البخاري ومسلم - خاتمة صحيح البخاري", referenceEn: "Sahih al-Bukhari & Sahih Muslim", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "من رحمة الله الواسعة بعباده أن جعل هذا الذكر اليسير في النطق يثقل موازين الحسنات يوم القيامة.", explanationEn: "Demonstrates Allah's boundless grace where lightweight words carry immense weight on the Scales of Eternity."),
        OfflineDailyHadith(id: "19", textAr: "اللَّهُمَّ أَنْتَ رَبِّي لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ.", translationEn: "O Allah, You are my Lord, none has the right to be worshipped but You. You created me and I am Your servant, and I abide by Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favors upon me and I acknowledge my sin, so forgive me, for none forgives sins except You.", translationTr: "", translationUr: "", narratorAr: "عن شداد بن أوس رضي الله عنه", narratorEn: "Narrated by Shaddad ibn Aws (RA)", referenceAr: "صحيح البخاري - أذكار الصباح والمساء", referenceEn: "Sahih al-Bukhari - Morning & Evening Dhikr", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "جامع للاعتراف بالربوبية والعبودية والنعمة والتقصير، ومن قاله موقناً به فمات في يومه أو ليلته دخل الجنة.", explanationEn: "Harmonizes acknowledgment of divine lordship, human servitude, gratitude for blessings, and contrite repentance."),
        OfflineDailyHadith(id: "20", textAr: "أَلاَ أَدُلُّكَ عَلَى كَلِمَةٍ هِيَ كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ؟ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ.", translationEn: "Shall I not guide you to a word which is a treasure from the treasures of Paradise? 'La hawla wa la quwwata illa billah' (There is no power nor might except with Allah).", translationTr: "", translationUr: "", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa Al-Ash'ari (RA)", referenceAr: "صحيح البخاري ومسلم", referenceEn: "Sahih al-Bukhari & Sahih Muslim", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "التبرؤ من الحول والقوة وتفويض الأمر كله لله القوي العزيز، وهي ذخر عظيم لصاحبها في الجنة.", explanationEn: "Acknowledges that all ability and transformation belong exclusively to Allah, storing perpetual treasures in Paradise."),
        OfflineDailyHadith(id: "21", textAr: "دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ؛ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلاَّ اسْتَجَابَ اللَّهُ لَهُ.", translationEn: "The supplication of Dhun-Nun when he called upon Allah inside the belly of the whale: 'La ilaha illa Anta, Subhanaka inni kuntu minaz-zalimeen' (There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers). No Muslim ever supplicates with it for anything except that Allah answers him.", translationTr: "", translationUr: "", narratorAr: "عن سعد بن أبي وقاص رضي الله عنه", narratorEn: "Narrated by Sa'd ibn Abi Waqqas (RA)", referenceAr: "سنن الترمذي ومستدرك الحاكم (صحيح) - باب دعاء الكرب", referenceEn: "Sunan at-Tirmidhi & Mustadrak al-Hakim (Sahih)", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "أعظم دعاء لكشف الشدائد وتفريج الكرب؛ جمع بين التوحيد والتنزيه والاعتراف بالذنب.", explanationEn: "The ultimate prayer for relief from agony and tribulation, unifying Monotheism, adoration, and humble contrition."),
        OfflineDailyHadith(id: "22", textAr: "أَحَبُّ الْكَلاَمِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، لاَ يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ.", translationEn: "The most beloved words to Allah are four: 'Subhan Allah, wal-Hamdu lillah, wa La ilaha illa Allah, wallahu Akbar' (Glory be to Allah, praise be to Allah, there is no god but Allah, and Allah is the Greatest). It does not matter with which of them you begin.", translationTr: "", translationUr: "", narratorAr: "عن سمرة بن جندب رضي الله عنه", narratorEn: "Narrated by Samurah ibn Jundub (RA)", referenceAr: "صحيح مسلم - باب فضل التسبيح والتحميد", referenceEn: "Sahih Muslim - Chapter on Tasbih & Tahmid", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "هذه الكلمات الأربع هي الباقيات الصالحات وغراس الجنة، وأحب الذكر إلى الله بعد القرآن الكريم.", explanationEn: "These four phrases form the everlasting righteous deeds, seedlings of Paradise, and the dearest words to Allah."),
        OfflineDailyHadith(id: "23", textAr: "مَنْ صَلَّى عَلَيَّ صَلاَةً وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا، وَحَطَّ عَنْهُ عَشْرَ خَطِيئَاتٍ، وَرَفَعَ لَهُ عَشْرَ دَرَجَاتٍ.", translationEn: "Whoever sends blessings upon me once, Allah will send ten blessings upon him, erase ten sins from him, and raise him ten degrees in status.", translationTr: "", translationUr: "", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "سنن النسائي ومسند أحمد (صحيح) - باب فضل الصلاة على النبي", referenceEn: "Sunan an-Nasa'i & Musnad Ahmad (Sahih)", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "الصلاة على النبي صلى الله عليه وسلم سبب لمغفرة الذنوب وكفاية الهموم ونيل شفاعته ورفعة الدرجات في الدنيا والآخرة.", explanationEn: "Supplicating blessings upon the Prophet grants relief from grief, forgiveness of sins, high ranks, and intercession."),
        OfflineDailyHadith(id: "101", textAr: "أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِكُمْ، يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسًا، مَا تَقُولُ ذَلِكَ يُبْقِي مِنْ دَرَنِهِ». قَالُوا لاَ يُبْقِي مِنْ دَرَنِهِ شَيْئًا. قَالَ «فَذَلِكَ مِثْلُ الصَّلَوَاتِ الْخَمْسِ، يَمْحُو اللَّهُ بِهَا الْخَطَايَا».", translationEn: "I heard Allah's Messenger (ﷺ) saying, \"If there was a river at the door of anyone of you and he took a bath in it five times a day would you notice any dirt on him?\" They said, \"Not a trace of dirt would be left.\" The Prophet (ﷺ) added, \"That is the example of the five prayers with which Allah blots out (annuls) evil deeds.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem: \"Sizden birinizin kapısının önünden günde beş kez yıkandığı bir nehir aksa, ne dersiniz bu yıkanma onun üzerinde bir kir bırakır mı?\" diye sordu. Ashâb-ı kiram, \"Kirden eser bırakmaz\" diye cevap verdi. Bunun üzerine Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Beş vakit namaz da böyledir. Onlar sayesinde Allah, günahları siler.\"", translationUr: "انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرماتے تھے کہ اگر کسی شخص کے دروازے پر نہر جاری ہو اور وہ روزانہ اس میں پانچ پانچ دفعہ نہائے تو تمہارا کیا گمان ہے۔ کیا اس کے بدن پر کچھ بھی میل باقی رہ سکتا ہے؟ صحابہ نے عرض کی کہ نہیں یا رسول اللہ! ہرگز نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ یہی حال پانچوں وقت کی نمازوں کا ہے کہ اللہ پاک ان کے ذریعہ سے گناہوں کو مٹا دیتا ہے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٥٢٨)", referenceEn: "Sahih al-Bukhari 528", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "102", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «صَلاَةُ الْجَمَاعَةِ تَفْضُلُ صَلاَةَ الْفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً».", translationEn: "Allah's Messenger (ﷺ) said, \"The prayer in congregation is twenty seven times superior to the prayer offered by a person alone.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem'in şöyle buyurduğu nakledilmiştir: \"Cemaatle kılınan namaz, tek başına kılınan namazdan yirmi yedi derece daha üstündür.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ جماعت کے ساتھ نماز اکیلے نماز پڑھنے سے ستائیس درجہ زیادہ فضیلت رکھتی ہے۔", narratorAr: "عن عبد الله بن عمر رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Umar (RA)", referenceAr: "رواه البخاري (٦٤٥)", referenceEn: "Sahih al-Bukhari 645", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "103", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «مَنْ صَلَّى الْبَرْدَيْنِ دَخَلَ الْجَنَّةَ».", translationEn: "Allah's Messenger (ﷺ) said, \"Whoever prays the two cool prayers ('Asr and Fajr) will go to Paradise.\"", translationTr: "Allah Resulü (Sallallahu Aleyhi ve Sellem)'in şöyle dediğini nakletmiştir: \"iki serin vakitteki namazları kim kılarsa cennete girer.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جس نے ٹھنڈے وقت کی دو نمازیں ( وقت پر ) پڑھیں ( فجر اور عصر ) تو وہ جنت میں داخل ہو گا۔", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa al-Ash'ari (RA)", referenceAr: "رواه البخاري (٥٧٤)", referenceEn: "Sahih al-Bukhari 574", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "104", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكْثِرُوا الدُّعَاءَ».", translationEn: "Abu Huraira reported: The Messenger of Allah (ﷺ) said: The nearest a servant comes to his Lord is when he is prostrating himself, so make supplication (in this state)", translationTr: "Resulullah (Sallallahu Aleyhi ve Sellem): «Kulun rabbine en yakın olduğu hâl secdede bulunduğu hâldir. Binaenaleyh siz (secdede) duayı çok edin!» buyurmuşlar.", translationUr: "رسول اللہﷺ نے فرمایا : ’’بندہ اپنے رب کے سب سے زیادہ قریب اس حالت میں ہوتا ہے جب وہ سجدے میں ہوتا ہے، لہٰذا اس میں کثرت سے دعا کرو۔‘‘", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٤٨٢)", referenceEn: "Sahih Muslim 482", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "105", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ».", translationEn: "Abu Huraira reported that the Messenger of Allah (ﷺ) said: The five (daily) prayers and one Friday prayer to (the next) Friday prayer are expiations (for the sins committed in the intervals) between them.", translationTr: "Nebi (Sallallahu aleyhi ve Sellem)'den şöyle buyurduğunu nakletti: \"Beş vakit namaz, bir sonraki cumaya kadar Cuma namazı aralarındaki (günah)lar için kefarettir.\"", translationUr: "نبی ﷺ سے روایت کی، آپ نے فرمایا : ’’ پانچوں نمازیں اور ایک جمعہ ( دوسرے ) جمعہ تک درمیانی مدت کے گناہوں کاکفارہ ہیں۔‘‘", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٢٣٣)", referenceEn: "Sahih Muslim 233", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "106", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ».", translationEn: "Allah's Messenger (ﷺ) said, \"Whoever observes fasts during the month of Ramadan out of sincere faith, and hoping to attain Allah's rewards, then all his past sins will be forgiven.\"", translationTr: "Resulullah sallallahu aleyhi ve sellem buyurdu ki: \"Kim inanarak ve sevabını yalnızca Allah'tan umarak Ramazan orucunu tutarsa geçmiş günahları bağışlanır.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا جس نے رمضان کے روزے ایمان اور خالص نیت کے ساتھ رکھے اس کے پچھلے گناہ بخش دیئے گئے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٣٨)", referenceEn: "Sahih al-Bukhari 38", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "107", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «يَقُولُ اللَّهُ عَزَّ وَجَلَّ الصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ يَدَعُ شَهْوَتَهُ وَأَكْلَهُ وَشُرْبَهُ مِنْ أَجْلِي، وَالصَّوْمُ جُنَّةٌ، وَلِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ حِينَ يُفْطِرُ وَفَرْحَةٌ حِينَ يَلْقَى رَبَّهُ، وَلَخَلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ».", translationEn: "The Prophet (ﷺ) said, \"Allah said: The Fast is for Me and I will give the reward for it, as he (the one who observes the fast) leaves his sexual desire, food and drink for My Sake. Fasting is a screen (from Hell) and there are two pleasures for a fasting person, one at the time of breaking his fast, and the other at the time when he will meet his Lord. And the smell of the mouth of a fasting person is better in Allah's Sight than the smell of musk.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle haber vermiştir: Aziz ve celil olan Allah şöyle buyurur: 'Oruç benim içindir. Onun mükafatını ancak ben veririm. Oruçlu kişi şehvetini, yemesini, içmesini benim için terkeder. Oruç bir kalkandır. Oruçlu için iki sevinç anı vardır: Biri iftar ederken duyduğu sevinç, biri de (kıyamet günü) Rabbine kavuşurken duyacağı sevinç. Yemin olsun ki, oruçlu ağzın açlık kokusu, Allah katında misk kokusundan daha hoştur.", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا ”اللہ عزوجل فرماتا ہے کہ روزہ خالص میرے لیے ہوتا ہے اور میں ہی اس کا بدلہ دیتا ہوں۔ بندہ اپنی شہوت، کھانا پینا میری رضا کے لیے چھوڑتا ہے اور روزہ گناہوں سے بچنے کی ڈھال ہے اور روزہ دار کے لیے دو خوشیاں ہیں۔ ایک خوشی اس وقت جب وہ افطار کرتا ہے اور ایک خوشی اس وقت جب وہ اپنے رب سے ملتا ہے اور روزہ دار کے منہ کی بو، اللہ کے نزدیک مشک عنبر کی خوشبو سے زیادہ پاکیزہ ہے۔“", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٧٤٩٢)", referenceEn: "Sahih al-Bukhari 7492", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "108", textAr: "قَالَ النَّبِيُّ صلى الله عليه وسلم «تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً».", translationEn: "The Prophet (ﷺ) said, \"Take Suhur as there is a blessing in it.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Sahur yapın! Çünkü sahurda bereket vardır.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، سحری کھاؤ کہ سحری میں برکت ہوتی ہے۔", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (١٩٢٣)", referenceEn: "Sahih al-Bukhari 1923", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "109", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ فَلَيْسَ لِلَّهِ حَاجَةٌ فِي أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ».", translationEn: "The Prophet (ﷺ) said, \"Whoever does not give up forged speech and evil actions, Allah is not in need of his leaving his food and drink (i.e. Allah will not accept his fasting)\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Yalan söylemeyi ve bu yalancı şahitliği bırakmayan kimsenin yemeyi ve içmeyi bırakmasına Allah'ın asla ihtiyacı yoktur.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، اگر کوئی شخص جھوٹ بولنا اور دغا بازی کرنا ( روزے رکھ کر بھی ) نہ چھوڑے تو اللہ تعالیٰ کو اس کی کوئی ضرورت نہیں کہ وہ اپنا کھانا پینا چھوڑ دے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (١٩٠٣)", referenceEn: "Sahih al-Bukhari 1903", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "110", textAr: "سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ بَاعَدَ اللَّهُ وَجْهَهُ عَنِ النَّارِ سَبْعِينَ خَرِيفًا».", translationEn: "Abu Sa'id al-Khudri (Allah be pleased with him) reported Allah's Messenger (ﷺ) as saying: He who observes fast for a day in the way of Allah He would remove his face from the Hell to the extent of seventy years' distance.", translationTr: "Ben Resulullah (Sallallahu Aleyhi ve Sellem): «Her kim Allah yolunda bir gün oruç tutarsa Allah o kimsenin yüzünü yetmiş yıl cehennemden ırak eyler, buyururken işittim.»", translationUr: "میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا : \" جس نے اللہ کی راہ میں ایک دن کا روزہ رکھا اللہ تعا لیٰ اس کے چہرے کو ( جہنم کی ) آگ سے ستر سال کی مسافت تک دور کر دیتا ہے۔\"", narratorAr: "عن أبي سعيد الخدري رضي الله عنه", narratorEn: "Narrated by Abu Sa'id al-Khudri (RA)", referenceAr: "رواه مسلم (١١٥٣)", referenceEn: "Sahih Muslim 1153", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "111", textAr: "عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ «مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلاَّ عِزًّا وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلاَّ رَفَعَهُ اللَّهُ».", translationEn: "Abu Huraira reported Allah's Messenger (ﷺ) as saying: Charity does not decrease wealth, no one forgives another except that Allah increases his honor, and no one humbles himself for the sake of Allah except that Allah raises his status.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem)’den naklen rivayet etti: «Sadaka hiç bir malı eksiltmez. Af sebebiyle Allah bir kulun ancak Şerefini artırır. Ve bir kimse Allah için tevazu gösterirse Allah onu ancak yükseltir.» buyurmuşlar.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" صدقے نے مال میں کبھی کوئی کمی نہیں کی اور معاف کرنے سے اللہ تعالیٰ بندے کو عزت ہی میں بڑھاتا ہے اور کوئی شخص ( صرف اور صرف ) اللہ کی خاطر تواضع ( انکسار ) اختیار نہیں کرتا مگر اللہ تعالیٰ اس کا مقام بلند کر دیتا ہے۔\"", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٢٥٨٨)", referenceEn: "Sahih Muslim 2588", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "112", textAr: "سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ».", translationEn: "\"Save yourself from Hell-fire even by giving half a date-fruit in charity.\"", translationTr: "Rasûlullah Sallallahu Aleyhi ve Sellem'in şöyle buyurduğunu işittim demiştir: \"Yarım hurmayla bile olsa cehennemden korunun.\"", translationUr: "میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ کہتے سنا کہ جہنم سے بچو اگرچہ کھجور کا ایک ٹکڑا دے کر ہی سہی ( مگر ضرور صدقہ کر کے دوزخ کی آگ سے بچنے کی کوشش کرو )۔", narratorAr: "عن عدي بن حاتم رضي الله عنه", narratorEn: "Narrated by Adi ibn Hatim (RA)", referenceAr: "رواه البخاري (١٤١٧)", referenceEn: "Sahih al-Bukhari 1417", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "113", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ، وَخَيْرُ الصَّدَقَةِ عَنْ ظَهْرِ غِنًى، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ».", translationEn: "The Prophet (ﷺ) said, \"The upper hand is better than the lower hand (i.e. he who gives in charity is better than him who takes it). One should start giving first to his dependents. And the best object of charity is that which is given by a wealthy person (from the money which is left after his expenses). And whoever abstains from asking others for some financial help, Allah will give him and save him from asking others, Allah will make him self-sufficient.\"", translationTr: "", translationUr: "", narratorAr: "عن حكيم بن حزام رضي الله عنه", narratorEn: "Narrated by Hakim ibn Hizam (RA)", referenceAr: "رواه البخاري (١٤٢٧)", referenceEn: "Sahih al-Bukhari 1427", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "114", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «كُلُّ مَعْرُوفٍ صَدَقَةٌ».", translationEn: "The Prophet (ﷺ) said, \"Every good deed is a Sadaqa.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem: \"Her maruf (iyilik) bir sadakadır\" buyurdu.", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا ”ہر نیک کام صدقہ ہے۔“", narratorAr: "عن جابر بن عبد الله رضي الله عنهما", narratorEn: "Narrated by Jabir ibn Abdullah (RA)", referenceAr: "رواه البخاري (٦٠٢١)", referenceEn: "Sahih al-Bukhari 6021", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "115", textAr: "أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ «مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلاَّ مَلَكَانِ يَنْزِلاَنِ فَيَقُولُ أَحَدُهُمَا اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الآخَرُ اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا».", translationEn: "The Prophet (ﷺ) said, \"Every day two angels come down from Heaven and one of them says, 'O Allah! Compensate every person who spends in Your Cause,' and the other (angel) says, 'O Allah! Destroy every miser.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Her gün, dünyaya iki melek iner ve bunlardan biri «Allah'ım! İnfak eden kişiye yenisini ver», diğeri de «Allah'ım! Vermeyenin malını telef et» der.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا، کوئی دن ایسا نہیں جاتا کہ جب بندے صبح کو اٹھتے ہیں تو دو فرشتے آسمان سے نہ اترتے ہوں۔ ایک فرشتہ تو یہ کہتا ہے کہ اے اللہ! خرچ کرنے والے کو اس کا بدلہ دے۔ اور دوسرا کہتا ہے کہ اے اللہ! «ممسك» اور بخیل کے مال کو تلف کر دے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (١٤٤٢)", referenceEn: "Sahih al-Bukhari 1442", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "116", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ».", translationEn: "The Prophet (ﷺ) said, \"The best among you (Muslims) are those who learn the Qur'an and teach it.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem'in şöyle buyurduğu rivayet edilmiştir: \"Sizin en hayırlınız Kur'an'ı öğrenen ve öğretendir.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ تم میں سب سے بہتر وہ ہے جو قرآن مجید پڑھے اور پڑھائے۔", narratorAr: "عن عثمان بن عفان رضي الله عنه", narratorEn: "Narrated by Uthman ibn Affan (RA)", referenceAr: "رواه البخاري (٥٠٢٧)", referenceEn: "Sahih al-Bukhari 5027", categoryAr: "القرآن الكريم", categoryEn: "The Quran", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "117", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ».", translationEn: "A'isha reported Allah's Messenger (ﷺ) (as saying): One who is proficient in the Qur'an is associated with the noble, upright, recording angels; and he who falters in it, and finds it difficult for him, will have two rewards.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem): «Kur'ân'da mahir olan sefere denilen kerîm ve muti' Nebilerle beraber olacakdır. Kur'ân-ı kekeleyerek güç hâl ile okuyana ise iki ecir vardır.» buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قرآن مجید کا ماہر قرآن لکھنے والے انتہائی معزز اور اللہ تعالیٰ کے فرمانبردار فرشتوں کے ساتھ ہوگا اور جو انسان قرآن مجید پڑھتا ہے اور ہکلاتا ہے۔ اور وہ ( پڑھنا ) اس کے لئے مشقت کا باعث ہے، اس کے لئے دو اجر ہیں۔\"", narratorAr: "عن أم المؤمنين عائشة رضي الله عنها", narratorEn: "Narrated by Aishah, Mother of the Believers (RA)", referenceAr: "رواه مسلم (٧٩٨)", referenceEn: "Sahih Muslim 798", categoryAr: "القرآن الكريم", categoryEn: "The Quran", explanationAr: "", explanationEn: ""),
    ]

    public static func verseForDayIndex(_ dayIndex: Int) -> OfflineDailyVerse {
        let idx = ((dayIndex % verses.count) + verses.count) % verses.count
        return verses[idx]
    }

    public static func hadithForDayIndex(_ dayIndex: Int) -> OfflineDailyHadith {
        let idx = ((dayIndex % hadiths.count) + hadiths.count) % hadiths.count
        return hadiths[idx]
    }
}
